source('services/analysis/tests/test_engine.R')
same<-function(a,b,label)check(isTRUE(all.equal(a,b,check.attributes=FALSE)),label)
d<-fixture(matrix(c(1,2,3,4,2,4,6,8),4))
before<-serialize(d,NULL);invisible(fit_recipe(d,list()));check(identical(before,serialize(d,NULL)),'input immutable')
same(fit_recipe(d,list(normalize=list(method='sum',target=100)))$matrix,row_normalized<-d$matrix |> unlist() |> matrix(nrow=4,byrow=TRUE) / rowSums(as_rows(d$matrix,4,2))*100,'sum normalization')
z<-fixture(matrix(c(1,NA,3,4,2,4,6,8),4));p<-fit_recipe(z,list(impute=list(method='median')));check(p$matrix[2,1]==3,'median imputation')
p<-fit_recipe(z,list(impute=list(method='half-minimum')));check(p$matrix[2,1]==.5,'half minimum positive')
training<-fit_recipe(d,list(impute=list(method='median'),scale=list(method='uv')),training_ids=c('s1','s2','s3'))
held<-fixture(matrix(c(1000,2000),1),groups='T');held$samples[[1]]$id<-'new';same(apply_recipe(held,training$state)$matrix,(matrix(c(1000,2000),1)-matrix(training$state$scale$center,1))/matrix(training$state$scale$denom,1),'held out never refits scale')
err(fit_recipe(fixture(matrix(c(0,0,0,0,1,2,3,4),4)),list(scale=list(method='uv'))),'SCALE_ZERO_OR_UNDEFINED')
check(length(fit_recipe(fixture(matrix(c(0,0,0,0,1,2,3,4),4)),list(filter=list(zeroVariance='drop')))$featureIds)==1,'zero variance explicit filtering')
err(fit_recipe(z,list(transform=list(method='log2',pseudocount=-1))),'PSEUDOCOUNT')
zero<-fixture(matrix(c(0,1,2,3,4,5,6,7),4));err(fit_recipe(zero,list(transform=list(method='ln'))),'TRANSFORM_DOMAIN')
check(is.finite(fit_recipe(zero,list(transform=list(method='ln',pseudocount=1)))$matrix[1,1]),'explicit pseudocount')
mixed<-d;mixed$features[[2]]$unit<-'area';err(fit_recipe(mixed),'MIXED_UNITS_ACKNOWLEDGEMENT_REQUIRED');check(ncol(fit_recipe(mixed,list(filter=list(allowMixedUnits=TRUE)))$matrix)==2,'mixed unit acknowledgement')
q<-d;q$quality$cellStates[[1]][[1]]<-'original-imputed';q$quality$cellStates[[2]][[1]]<-'unknown';check(sum(is.finite(prepare_independent(q)$matrix[,1]))==2,'inference excludes original imputed and unknown')
paired<-fixture(matrix(c(1,3,2,4,3,5,4,6),4),c('C','T','C','T'));for(i in 1:4)paired$samples[[i]]$subjectId<-paste0('subject',ceiling(i/2))
res<-analyze_dataset(paired,list(),list(method='compare',test='paired-wilcoxon',control='C',treatment='T'));check(res$data$results[[1]]$nControl==2,'paired valid subjects')
paired$samples[[4]]$subjectId<-'other';err(analyze_dataset(paired,list(),list(method='compare',test='paired-t',control='C',treatment='T')),'PAIRED_SUBJECT_MISMATCH')
hm<-analyze_dataset(d,list(),list(method='heatmap',displayScale='feature-z',clusterRows=FALSE));same(hm$data$analysisMatrix,as_rows(d$matrix,4,2),'heatmap display preserves analysis matrix');check(is.null(hm$data$rowTree),'independent row cluster switch')
err(analyze_dataset(d,list(),list(method='heatmap',rowDistance='pearson',rowLinkage='ward.D2')),'WARD_REQUIRES_EUCLIDEAN')
dist<-analyze_dataset(d,list(),list(method='distribution'));check(length(dist$data$points)==4,'distribution independent point count')
check(length(dist$data$composition)==4,'composition emits separately normalized nonnegative proportions')
cat('EDGE TESTS PASSED\n')
